function write(string $dir, string $domain, array $units): void
{
    foreach (['de' => 0, 'en' => 1] as $lang => $i) {
        $x = "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<xliff xmlns=\"urn:oasis:names:tc:xliff:document:1.2\" version=\"1.2\">\n  <file source-language=\"en\" target-language=\"$lang\" datatype=\"plaintext\" original=\"$domain.en.xliff\">\n    <body>\n";
        foreach ($units as $key => $texts) {
            $id = substr(strtr(base64_encode(md5($key, true)), '+/', '-_'), 0, 7);
            $x .= "      <trans-unit id=\"$id\" resname=\"$key\">\n        <source>$key</source>\n        <target>" . htmlspecialchars($texts[$i], ENT_XML1) . "</target>\n      </trans-unit>\n";
        }
        $x .= "    </body>\n  </file>\n</xliff>\n";
        file_put_contents("$dir/$domain.$lang.xlf", $x);
    }
}

$dir = \dirname(__DIR__) . '/Resources/translations';
